def separate_paren_groups(paren_string: str) -> List[str]:
    result = []
    stack = []
    current_group = []

    for char in paren_string.replace(" ", ""):
        if char == '(':
            stack.append(char)
            current_group.append(char)
        elif char == ')':
            if stack and stack[-1] == '(':
                stack.pop()
                current_group.append(char)
                if not stack:
                    result.append(''.join(current_group))
                    current_group = []
            else:
                raise ValueError("Unbalanced parentheses")

    if stack:
        raise ValueError("Unbalanced parentheses")

    return result

