def max_product(num_str: str, N: int, K: int) -> int:
    if N - K - 1 < 0:
        return 0

    num_list = [int(digit) for digit in num_str]

    while K > 0:
        max_product = 0
        max_index = 0
        for i in range(N - 1):
            product = num_list[i] * num_list[i + 1]
            if product > max_product:
                max_product = product
                max_index = i
        num_list.insert(max_index + 1, 0)
        K -= 1

    result = 1
    for num in num_list:
        result *= num

    return result

