def count_passing_ways(n: int, m: int) -> int:
    # Initialize a 2D array to store the number of ways to reach each student after a given number of passes
    dp = [[0 for _ in range(n)] for _ in range(m + 1)]

    # There's one way to be at the starting student before any passes
    for i in range(n):
        dp[0][i] = 1

    # Iterate over the number of passes
    for pass_count in range(1, m + 1):
        for student in range(n):
            # The number of ways to reach the current student is the sum of the ways to reach the students on either side
            dp[pass_count][student] = dp[pass_count - 1][(student - 1) % n] + dp[pass_count - 1][(student + 1) % n]

    # The result is the number of ways to be back at the starting student after 'm' passes
    return dp[m][0]

