    """
    Calculates the score of a series of ping-pong games based on the provided scoring system.

    Args:
    - system (int): The number of points required to win a game (either 11 or 21).
    - points (str): A string of 'W' and 'L' characters denoting points won by the player and opponent.

    Returns:
    - list: A list of strings representing the score of each game.
    """

    def reset_score():
        return {"player": 0, "opponent": 0}

    def game_finished(scores):
        return scores["player"] >= system or scores["opponent"] >= system

    def has_lead(scores):
        return abs(scores["player"] - scores["opponent"]) >= 2

    game_scores = []
    scores = reset_score()

    for point in points:
        if point == 'W':
            scores["player"] += 1
        elif point == 'L':
            scores["opponent"] += 1

        if game_finished(scores) and has_lead(scores):
            game_scores.append(f"{scores['player']}:{scores['opponent']}")
            scores = reset_score()

    if scores["player"] > 0 or scores["opponent"] > 0:
        game_scores.append(f"{scores['player']}:{scores['opponent']}")

    return game_scores

