def catalan_number(n: int) -> int:
    # Initialize a list to store the Catalan numbers
    catalan = [0] * (n + 1)

    # The base case
    catalan[0] = 1

    # Compute the Catalan numbers using the dynamic programming approach
    for i in range(1, n + 1):
        for j in range(i):
            catalan[i] += catalan[j] * catalan[i - j - 1]

    return catalan[n]

