def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    # Initialize a DP array where dp[i][j] represents the maximum value that can be obtained
    # with the first i herbs within time j
    dp = [[0 for _ in range(T + 1)] for _ in range(M + 1)]

    # Fill the DP table
    for i in range(1, M + 1):
        time, value = herbs[i - 1]
        for j in range(1, T + 1):
            if time <= j:
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - time] + value)
            else:
                dp[i][j] = dp[i - 1][j]

    # The maximum value is found in the last cell of the table
    return dp[M][T]

