    right = [1] * n

    # Compute the increasing subsequence lengths
    for i in range(1, n):
        for j in range(i):
            if heights[i] > heights[j]:
                left[i] = max(left[i], left[j] + 1)

    # Compute the decreasing subsequence lengths
    for i in range(n-2, -1, -1):
        for j in range(i+1, n):
